package ru.neverland.townyjustice;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import ru.neverland.core.*;
import static ru.neverland.townyjustice.JusticeDossiers.*;
public final class JusticeDossiersSmoke {
    static int checks;interface Work{void run()throws Exception;}static void check(boolean good,String why){checks++;if(!good)throw new AssertionError(why);}static void denied(Work work,String why)throws Exception{try{work.run();}catch(Exception expected){check(true,why);return;}throw new AssertionError(why);}static <T>T done(CompletionStage<T> task)throws Exception{return task.toCompletableFuture().get(5,TimeUnit.SECONDS);}
    public static void main(String[] args)throws Exception{
        UUID town=UUID.randomUUID(),caseId=UUID.randomUUID(),subject=UUID.randomUUID(),judge=UUID.randomUUID(),worker=UUID.randomUUID(),incident=UUID.randomUUID();var empty=Dossier.empty(caseId,town,subject);var assigned=empty.assign(judge,worker,100);check(assigned.revision()==1&&assigned.assigned().equals(worker)&&assigned.history().size()==1,"assignment is an auditable immutable change");check(assigned.assign(judge,worker,500)==assigned,"repeated assignment idempotent");
        var fact=Evidence.note(caseId,subject,"Объяснение участника дела",110);var noted=assigned.add(fact);check(noted.add(Evidence.note(caseId,subject,"Объяснение участника дела",900))==noted,"repeat identical explanation never duplicates evidence or history");var source=new Evidence("crime:"+incident,judge,120,"CRIME",incident.toString(),"Подтверждённое происшествие города; виновник не установлен");var linked=noted.add(source);check(linked.add(new Evidence(source.id(),subject,999,source.source(),source.reference(),source.description()))==linked,"same incident linked exactly once regardless repeated importing actor/time");denied(()->linked.add(new Evidence(source.id(),judge,130,"CRIME",incident.toString(),"Другие недостоверные сведения")),"same evidence ID cannot silently change content");
        var appealed=linked.appeal(subject,"Прошу проверить обстоятельства дела",150);check(appealed.appeals().size()==1&&appealed.appeals().get(0).outcome()==Outcome.OPEN,"appeal begins open without inventing decision");denied(()->appealed.appeal(subject,"Повторное заявление на те же обстоятельства",151),"one open appeal per case");denied(()->linked.appeal(worker,"Заявление от постороннего",151),"only subject may appeal");denied(()->appealed.decide(subject,Outcome.UPHELD,"Подтверждаю собственное заявление",200),"self review is forbidden");var decided=appealed.decide(judge,Outcome.RECONSIDER,"Нужна дополнительная проверка, затем отдельное решение",200);check(decided.appeals().get(0).outcome()==Outcome.RECONSIDER&&decided.appeals().get(0).reviewer().equals(judge)&&decided.history().get(decided.history().size()-1).action().equals("RECONSIDER"),"independent reasoned decision and full actor history retained");denied(()->decided.decide(judge,Outcome.UPHELD,"Повторный ответ по закрытому заявлению",201),"closed appeal cannot be rewritten");check(appealed.appeals().get(0).outcome()==Outcome.OPEN,"previous immutable snapshot unaffected");
        var state=State.empty().put(assigned);state=state.put(noted);state=state.put(linked);state=state.put(appealed);state=state.put(decided);var confirmed=state;var second=Dossier.empty(UUID.randomUUID(),town,subject).add(source);denied(()->confirmed.put(second),"same source incident cannot be assigned to a second case");denied(()->new Evidence("crime:"+incident,judge,120,"NOTE",incident.toString(),"Сведения с подменённым источником"),"source namespace validated");denied(()->Evidence.note(caseId,subject,"Поддельный\nперенос",0),"control sequences rejected");denied(()->Evidence.note(caseId,subject,"x".repeat(601),0),"explanation bounded");
        var full=empty;for(int i=0;i<32;i++)full=full.add(Evidence.note(caseId,subject,"Сведения номер "+i,i));var capped=full;denied(()->capped.add(Evidence.note(caseId,subject,"Сведения сверх предела",33)),"per-case evidence hard cap");
        Path dir=Files.createTempDirectory("justice-dossiers-"),file=dir.resolve("dossiers.yml");var repo=new JusticeDossiersRepository(file);repo.load();done(repo.commit(repo.state(),confirmed));check(repo.state().equals(confirmed),"accepted dossier state published after write");
        var before=repo.state();var next=before.put(decided.appeal(subject,"Есть новые дополнительные сведения для пересмотра",300));var field=AtomicFiles.class.getDeclaredField("writers");field.setAccessible(true);@SuppressWarnings("unchecked")var locks=(Map<Path,ReentrantLock>)field.get(null);var lock=locks.computeIfAbsent(file.toAbsolutePath().normalize(),key->new ReentrantLock());lock.lock();CompletionStage<State> pending;CompletionStage<Void> closing;
        try{pending=repo.commit(before,next);check(repo.busy()&&!pending.toCompletableFuture().isDone()&&repo.state().equals(before),"physically blocked file exposes no unconfirmed appeal");check(SuiteState.tryRun("justice review delayed IO",()->{}),"optional file delay never holds shared ledger");denied(()->done(repo.commit(before,State.empty())),"overlapping mutation rejected");closing=repo.prepareClose();check(!closing.toCompletableFuture().isDone(),"shutdown drains accepted appeal");}finally{lock.unlock();}done(closing);check(done(pending).equals(next),"accepted appeal survives drain");var loaded=new JusticeDossiersRepository(file);loaded.load();check(loaded.state().equals(next)&&loaded.state().dossiers().get(caseId).evidence().get(source.id()).equals(source),"restart preserves exact source evidence, assignment, appeal and full history");denied(()->done(loaded.commit(before,confirmed)),"stale compare-and-commit cannot erase newer accepted appeal");
        Files.delete(file);Files.createDirectory(file);Files.writeString(file.resolve("keep"),"block");var failed=next.put(next.dossiers().get(caseId).decide(judge,Outcome.UPHELD,"После независимой проверки оснований не обнаружено",350));denied(()->done(loaded.commit(next,failed)),"physical atomic replacement failure surfaced");check(loaded.readable()&&!loaded.writable()&&loaded.state().equals(next),"failed write preserves all confirmed records and closes further edits");done(loaded.prepareClose());
        Path corrupt=dir.resolve("corrupt.yml");Files.writeString(corrupt,"schema: 99\ndossiers: damaged\n");var bad=new JusticeDossiersRepository(corrupt);denied(bad::load,"unknown optional schema refused");check(!bad.readable()&&Files.readString(corrupt).equals("schema: 99\ndossiers: damaged\n"),"unknown optional sidecar never rewritten");done(bad.prepareClose());
        System.out.println("JusticeDossiersSmoke PASS "+checks+" checks");
    }
}
